* --- Analysis ---
.control
  * 1. AC Analysis for Open-Loop Gain and Phase Margin
  * Set DC operating point for linear operation
  alter @Vp[dc] = 0.9
  alter @Vin[dc] = 0.9
  alter @Vin[ac] = 1

  op
  ac dec 100 1 1G

  * Calculate Open-Loop Gain: A_OL = - Vout / vm
  let gain_db = vdb(Vout) - vdb(vm)

  * Calculate Phase Margin
  * Phase of A_OL = phase(Vout) - phase(vm)
  let phase_out = 180/PI * cph(v(Vout))
  let phase_m = 180/PI * cph(v(vm))
  let pm_curve = phase_out - phase_m

  meas ac open_loop_gain find gain_db at=10
  meas ac unity_gain_frequency when gain_db=0 fall=1
  meas ac phase_margin find pm_curve when gain_db=0 fall=1

  * 2. Transient Analysis for Slew Rate
  alter @Vin[ac] = 0
  alter @Vp[dc] = 0.5
  * Pulse from 0.1V to 0.9V
  alter @Vin[pulse] = [ 0.1 0.9 10n 1n 1n 500n 1u ]

  tran 1n 1.2u

  * Measure falling slew rate (Vout goes 0.9V -> 0.1V)
  meas tran t_fall trig v(Vout) val=0.8 fall=1 targ v(Vout) val=0.2 fall=1
  let slew_rate_fall = (0.8 - 0.2) / t_fall / 1e6
  print slew_rate_fall

  * Measure rising slew rate (Vout goes 0.1V -> 0.9V)
  meas tran t_rise trig v(Vout) val=0.2 rise=1 targ v(Vout) val=0.8 rise=1
  let slew_rate_rise = (0.8 - 0.2) / t_rise / 1e6
  print slew_rate_rise

  quit
.endc

